/**
 * Resolves a shared i18n key to its English string, interpolating
 * `{{name}}` placeholders from `vars`. Unknown keys come back as the key
 * itself so a missing entry is visible in the UI rather than blank.
 */
export function t(key, vars) {
  // i18next-style plural suffix: `{{count}}` of 1 picks `key_one`, else `key_other`.
  const pluralKey = vars && typeof vars.count === 'number' ? `${key}_${vars.count === 1 ? 'one' : 'other'}` : null;
  const template = (pluralKey && COACH_COPY[pluralKey]) ?? COACH_COPY[key] ?? key;
  if (!vars) return template;
  return template.replace(/\{\{(\w+)\}\}/g, (_, name) => (name in vars ? String(vars[name]) : `{{${name}}}`));
}

